/*\
title: $:/plugins/huwiki/ai/message-actions.js
type: application/javascript
module-type: library

Pure transformations of already received AI messages. No API or wiki writes.
\*/
(function(){
"use strict";
function linesOf(text){return String(text||"").replace(/\r\n/g,"\n").split("\n");}
function parseBlocks(text){
  var lines=linesOf(text),blocks=[],prose=[],code=[],lang="",fence="",opening="";
  function flush(){if(prose.length){blocks.push({kind:"text",text:prose.join("\n")});prose=[];}}
  lines.forEach(function(line){
    if(!fence){
      var m=line.match(/^\s*(`{3,}|~{3,})([^`~]*)$/);
      if(m){flush();fence=m[1];opening=line;lang=(m[2]||"").trim().toLowerCase();code=[];}
      else prose.push(line);
    }else{
      var close=line.match(/^\s*(`{3,}|~{3,})\s*$/);
      if(close&&close[1][0]===fence[0]&&close[1].length>=fence.length){
        blocks.push({kind:"code",language:lang,text:code.join("\n")});fence="";code=[];
      }else code.push(line);
    }
  });
  // Keep an unfinished fence as literal source, never unwrap it as executable WikiText.
  if(fence)blocks.push({kind:"incomplete",text:[opening].concat(code).join("\n")});
  flush();return blocks.filter(function(b){return b.text.trim().length>0;});
}
function codeBlocks(text){return parseBlocks(text).filter(function(b){return b.kind==="code";});}
function codeFence(block){
  var runs=String(block.text).match(/`{3,}/g)||[],size=3;
  runs.forEach(function(run){size=Math.max(size,run.length+1);});
  var fence=new Array(size+1).join("`");
  return fence+(block.language||"")+"\n"+block.text+"\n"+fence;
}
function normalizeProse(text,markdown){
  var lines=linesOf(text),out=[],stack=[];
  // # is a valid ordered-list marker in WikiText. Only treat it as a Markdown
  // heading when the document declares Markdown or contains clear Markdown cues.
  var md=!!markdown||/(^|\n)\s*[-+]\s+|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\(https?:\/\//.test(text);
  lines.forEach(function(line){
    var m,marker="",body=line,indent=0;
    if(md&&(m=line.match(/^(#{1,6})\s+(.+)$/))){
      body=new Array(m[1].length+1).join("!")+" "+m[2];stack=[];
    }else if((m=line.match(/^(\s*)([-+•◦▪‣]|\d+[.)]|\*)\s+(.+)$/))){
      indent=m[1].replace(/\t/g,"    ").length;marker=/\d/.test(m[2])?"#":"*";
      while(stack.length&&stack[stack.length-1].indent>indent)stack.pop();
      if(!stack.length||stack[stack.length-1].indent<indent)stack.push({indent:indent,marker:marker});
      else stack[stack.length-1].marker=marker;
      body=stack.map(function(s){return s.marker;}).join("")+" "+m[3];
    }else if(!/^\s*$/.test(line)){stack=[];}
    // Leave inline code, wiki links and HTML/widget attributes untouched.
    body=body.split(/(`+[^`]*`+|\[\[[\s\S]*?\]\]|<[^>]*>)/g).map(function(part,i){
      if(i%2)return part;
      return part.replace(/\*\*([^*\n]+)\*\*/g,"''$1''")
        .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g,"[[$1|$2]]");
    }).join("");
    // Block syntax needs a blank line after a preceding ordinary paragraph.
    if(/^(?:[!*#]+\s|\|)/.test(body)&&out.length&&out[out.length-1].trim()&&
        !/^(?:[!*#]+\s|\|)/.test(out[out.length-1]))out.push("");
    out.push(body);
  });return out.join("\n");
}
function toWikiText(text){
  var blocks=parseBlocks(text),markdown=false;
  if(blocks.length===1&&blocks[0].kind==="code"&&
      /^(wikitext|tiddlywiki|tw|tid|text\/vnd\.tiddlywiki|markdown|md)$/.test(blocks[0].language)){
    markdown=/^(markdown|md)$/.test(blocks[0].language);
    blocks=parseBlocks(blocks[0].text);
  }
  return blocks.map(function(b){
    if(b.kind==="code")return codeFence(b);
    if(b.kind==="incomplete")return codeFence({text:b.text,language:"text"});
    return normalizeProse(b.text,markdown);
  }).join("\n\n").trim();
}
function toWikiTextCode(text,selected){
  var items=codeBlocks(text).filter(function(b,i){return !Array.isArray(selected)||selected.indexOf(i)!==-1;});
  if(!items.length)throw new Error("Svaret indeholder ingen valgte kodeblokke.");
  return items.map(function(b){return b.text;}).join("\n\n").trim();
}
function proposedTitle(text,fallback){
  var s=toWikiText(text),heading=s.match(/^!{1,6}\s+(.+)$/m);
  var first=heading&&heading[1]||s.split(/\r?\n/).map(function(x){return x.trim();}).filter(Boolean)[0]||fallback||"AI-svar";
  first=first.replace(/[\x00-\x1f<>]/g," ").replace(/^[-*!# ]+/,"").replace(/[`*]/g,"").trim();
  return (first||fallback||"AI-svar").slice(0,85);
}
function getModeText(mode,text,selected){
  if(mode==="code")return toWikiTextCode(text,selected);
  if(mode==="full")return toWikiText(text);
  if(mode==="selected"){
    var chosen=parseBlocks(text).filter(function(b,i){return Array.isArray(selected)&&selected.indexOf(i)!==-1;});
    if(!chosen.length)throw new Error("Vælg mindst ét tekstafsnit eller én kodeblok.");
    return chosen.map(function(b){return b.kind==="text"?normalizeProse(b.text):codeFence(b);}).join("\n\n");
  }
  throw new Error("Ukendt indholdstype");
}
function messageProposals(messages,max){
  return (messages||[]).slice(-(max||12)).filter(function(m){return m&&String(m.text||"").trim();}).map(function(m,i){
    return {title:proposedTitle(m.text,"AI-besked "+(i+1)),tags:["HUWiki AI udtræk"],
      type:"text/vnd.tiddlywiki",text:toWikiText(m.text),selected:true,sourceMessage:m.title||""};
  });
}
exports.parseBlocks=parseBlocks;exports.codeBlocks=codeBlocks;exports.codeFence=codeFence;
exports.normalizeProse=normalizeProse;exports.toWikiText=toWikiText;
exports.toWikiTextCode=toWikiTextCode;exports.proposedTitle=proposedTitle;
exports.getModeText=getModeText;exports.messageProposals=messageProposals;
})();
